import SwiftUI
struct TemplatesView: View { @EnvironmentObject private var appState: AppState; @Namespace private var selection; var body: some View { NavigationStack { ScrollView(.horizontal,showsIndicators:false){ HStack(spacing:18){ForEach(ResumeTemplate.all){template in TemplateCardView(template:template,selected:appState.selectedTemplateID==template.id,namespace:selection).scaleEffect(appState.selectedTemplateID==template.id ? 0.98 : 1).onTapGesture{withAnimation(.selectionRing){appState.selectedTemplateID=template.id; appState.activeResume.templateID=template.id; appState.saveResume(); HapticManager.shared.softTap()}}}}.padding(20) }.background(DS.ColorToken.background.ignoresSafeArea()).navigationTitle("Templates").navigationBarTitleDisplayMode(.inline) } } }
